INSERT INTO risk_rules (rule_id, rule_code, rule_name, applies_to, threshold_logic, weight, enabled) VALUES
    ('9b16e305-4247-5021-a297-26dcdcfa42db', 'R-01', 'Near-Threshold Structuring', 'ALL', 'Three or more transactions in the trailing 7 days each sitting just under the 10,000 reporting threshold, together totalling 10,000 or more. Channel-agnostic: the same behaviour shows up in cards, transfers and crypto alike.', 44.00, TRUE),
    ('c9054430-bb1e-59f8-921d-7f4102168790', 'R-02', 'Elevated-Risk Payment Corridor', 'PAYMENT', 'A payment to a beneficiary bank in an elevated-risk jurisdiction (AF, HT, IR, KP, MM, SY or YE), where the customer has sent two or more such cross-border payments in the trailing 7 days, or their combined value in that window reaches 5,000 or more.', 32.00, TRUE),
    ('f02dec85-8f78-5068-9bd3-bbb1c46b82ad', 'R-03', 'Card-Not-Present Decline Cluster', 'CARD', 'Three or more card-not-present declines within a rolling 1-hour window, spread across two or more distinct merchants -- the pattern a stolen card number leaves while it is being validated.', 52.00, TRUE),
    ('8994143f-37ed-521f-9c6f-655f8cdc4094', 'R-04', 'Rapid Exchange Disposal', 'CRYPTO', 'Crypto that arrived in a wallet is sent on to a known exchange within 1 hour, with 10,000 or more having left that wallet over the trailing 24 hours.', 34.00, TRUE),
    ('145db118-5ca6-59dd-84a0-01a09d717d30', 'R-05', 'Flagged Wallet Proximity', 'CRYPTO', 'The sending wallet is within 2 hops of an address on the flagged-wallet watch list, found by a depth-limited walk of the wallet graph. Direct contact (0-1 hops) prices at the full weight; one intermediary wallet away (2 hops) prices at half.', 54.00, TRUE),
    ('621b88e5-d2b2-5ce5-85de-404f47c21754', 'R-06', 'Dormancy Burst', 'ALL', 'An account silent for 90 days or more suddenly transacts 5 or more times within a single day -- the shape a taken-over or rented account leaves behind.', 20.00, TRUE),
    ('84097565-beaf-5b1f-91c3-b094d4fbf37a', 'R-07', 'Quasi-Cash Concentration', 'CARD', '2,500 or more of a single day''s card spend concentrated at quasi-cash, money-transfer or gambling merchants -- the card-side equivalent of a cash machine.', 18.00, TRUE);
